int main(){ int n,k; cin>>n>>k; vector<long long> j(n); for(auto&x:j)cin>>x; int F=1<<n; vector<long long> sum(F,0);
  for(int s=1;s<F;s++){ int b=__builtin_ctz(s); sum[s]=sum[s&(s-1)]+j[b]; }
  vector<long long> dp(sum); for(int w=2;w<=k;w++){ vector<long long> nd(F); for(int s=0;s<F;s++){ long long best=dp[s]; for(int t=s;t;t=(t-1)&s) best=min(best,max(dp[s^t],sum[t])); nd[s]=best; } dp=nd; }
  cout<<dp[F-1]<<"\n"; }

